105		}
106		view, _ := r.Cargo("G1")
107		if view.Weight != 20 || view.Destination != "Shanghai" || !view.AllowMixed {
108			t.Fatalf("重复登记后原记录被改变: %+v", view)
109		}
110	}
111	
