		t.Fatal(err)
	}
	if _, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A2", []Op{{Kind: OpLoad, CargoID: "G2", Target: "C1"}}); err != nil {
