1	package stowage
2	
3	import (
4		"encoding/json"
5		"math"
6		"sort"
7		"strings"
8	)
9	
10	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
11	//
12	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
13	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
14	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
15	// 可以修正后重试。
16	//
17	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
18	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
19	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
20	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
21	// 范围也会被拒绝。
22	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
23		r.mu.Lock()
24		defer r.mu.Unlock()
25	
26		aid := strings.TrimSpace(adjustmentID)
27		if aid == "" {
28			return nil, fail(ErrInvalidID, "", "调整编号为空")
29		}
30	
31		// f 构造带调整编号的错误。
32		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
33			e := fail(kind, id, format, args...)
34			e.AdjustmentID = aid
35			return e
36		}
37	
38		// 幂等：编号已成功使用过。
39		if saved, ok := r.adjustments[aid]; ok {
40			if r.contents[aid] == canonicalKey(ops) {
41				return cloneResult(saved), nil
42			}
43			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
44		}
45	
46		if len(ops) == 0 {
47			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
48		}
49	
50		// 逐条校验操作本身的合法性。
51		vops, affected, verr := r.validateOps(ops)
52		if verr != nil {
53			verr.AdjustmentID = aid
54			return nil, verr
55		}
56	
57		// 在模拟配载上应用全部操作。
58		final := r.simulate(vops)
59	
60		// 按最终配载校验承重与混装限制。
61		for id, set := range final {
62			var sum int64
63			destinations := make(map[string]bool)
64			for _, c := range set {
65				if c.weight > math.MaxInt64-sum {
66					return nil, f(ErrOverflow, id, "舱位 %s 重量合计超过 int64 可表示范围", id)
67				}
68				sum += c.weight
69				destinations[c.destination] = true
70			}
71			if sum > r.compartments[id].maxWeight {
72				return nil, f(ErrOverweight, id, "舱位 %s 总重量 %d 千克超过最大承重 %d 千克", id, sum, r.compartments[id].maxWeight)
73			}
74			if len(destinations) > 1 {
75				for _, c := range set {
76					if !c.allowMixed {
77						return nil, f(ErrMixedLoading, c.id, "舱位 %s 存在不同目的地货物，但货物 %s 不允许混装", id, c.id)
78					}
79				}
80			}
81		}
82	
83		// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
84		cargoChanges := make([]CargoChange, 0, len(vops))
85		compChanges := make([]CompartmentChange, 0, len(affected))
86		for id := range affected {
87			compChanges = append(compChanges, CompartmentChange{
88				CompartmentID: id,
89				WeightBefore:  sumSet(r.compartments[id].cargo),
90				WeightAfter:   sumSet(final[id]),
91			})
92		}
93		sort.Slice(compChanges, func(i, j int) bool {
94			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
95		})
96	
97		for _, v := range vops {
98			c := v.cargo
99			from := c.compartmentID
100			var to string
101			switch v.op.Kind {
102			case OpLoad:
103				r.compartments[v.target.id].cargo[c.id] = c
104				c.compartmentID = v.target.id
105				to = v.target.id
106			case OpUnload:
107				delete(r.compartments[from].cargo, c.id)
108				c.compartmentID = ""
109			case OpMove:
110				delete(r.compartments[from].cargo, c.id)
111				r.compartments[v.target.id].cargo[c.id] = c
112				c.compartmentID = v.target.id
113				to = v.target.id
114			}
115			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
116		}
117		sort.Slice(cargoChanges, func(i, j int) bool {
118			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
119		})
120	
121		result := &AdjustmentResult{
122			ID:                 aid,
123			CargoChanges:       cargoChanges,
124			CompartmentChanges: compChanges,
125		}
126		r.adjustments[aid] = result
127		r.contents[aid] = canonicalKey(ops)
128		return cloneResult(result), nil
129	}
130	
131	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
132	// 即视为相同内容，排列顺序不影响判断。
133	func canonicalKey(ops []Op) string {
134		sorted := make([]Op, len(ops))
135		for i, op := range ops {
136			sorted[i] = Op{
137				Kind:    op.Kind,
138				CargoID: strings.TrimSpace(op.CargoID),
139				Target:  strings.TrimSpace(op.Target),
140			}
141		}
142		sort.Slice(sorted, func(i, j int) bool {
143			if sorted[i].Kind != sorted[j].Kind {
144				return sorted[i].Kind < sorted[j].Kind
145			}
146			if sorted[i].CargoID != sorted[j].CargoID {
147				return sorted[i].CargoID < sorted[j].CargoID
148			}
149			return sorted[i].Target < sorted[j].Target
150		})
151		b, err := json.Marshal(sorted)
152		if err != nil {
153			// Op 仅含基本类型，不会失败。
154			panic(err)
155		}
156		return string(b)
157	}
158	
159	// validOp 是一条通过逐条合法性校验的操作。
160	type validOp struct {
161		op     Op
162		cargo  *cargo
163		target *compartment // 装载/移动的目标舱位；卸下时为 nil
164	}
165	
166	// validateOps 逐条校验操作本身的合法性（调用方持锁）。
167	//
168	// 返回通过校验的操作与受影响舱位集合。任一操作不合法时，按输入顺序返回
169	// 第一个非法操作的现有错误种类及涉及对象，不返回局部结果。
170	func (r *Registry) validateOps(ops []Op) ([]validOp, map[string]bool, *Error) {
171		seen := make(map[string]bool)
172		vops := make([]validOp, 0, len(ops))
173		affected := make(map[string]bool)
174	
175		for _, op := range ops {
176			cid := strings.TrimSpace(op.CargoID)
177			if cid == "" {
178				return nil, nil, fail(ErrInvalidID, "", "货物编号为空")
179			}
180			c, ok := r.cargos[cid]
181			if !ok {
182				return nil, nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
183			}
184			if seen[cid] {
185				return nil, nil, fail(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
186			}
187			seen[cid] = true
188	
189			switch op.Kind {
190			case OpLoad:
191				if c.compartmentID != "" {
192					return nil, nil, fail(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
193				}
194				tid := strings.TrimSpace(op.Target)
195				if tid == "" {
196					return nil, nil, fail(ErrInvalidID, "", "目标舱位编号为空")
197				}
198				t, ok := r.compartments[tid]
199				if !ok {
200					return nil, nil, fail(ErrNotFound, tid, "舱位 %s 不存在", tid)
201				}
202				vops = append(vops, validOp{op, c, t})
203				affected[t.id] = true
204			case OpUnload:
205				if c.compartmentID == "" {
206					return nil, nil, fail(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
207				}
208				vops = append(vops, validOp{op, c, nil})
209				affected[c.compartmentID] = true
210			case OpMove:
211				if c.compartmentID == "" {
212					return nil, nil, fail(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
213				}
214				tid := strings.TrimSpace(op.Target)
215				if tid == "" {
216					return nil, nil, fail(ErrInvalidID, "", "目标舱位编号为空")
217				}
218				t, ok := r.compartments[tid]
219				if !ok {
220					return nil, nil, fail(ErrNotFound, tid, "舱位 %s 不存在", tid)
221				}
222				if t.id == c.compartmentID {
223					return nil, nil, fail(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
224				}
225				vops = append(vops, validOp{op, c, t})
226				affected[c.compartmentID] = true
227				affected[t.id] = true
228			default:
229				return nil, nil, fail(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
230			}
231		}
232		return vops, affected, nil
233	}
234	
235	// simulate 在配载副本上应用全部操作，返回最终配载（调用方持锁）。
236	// 不修改任何内部记录。
237	func (r *Registry) simulate(vops []validOp) map[string]map[string]*cargo {
238		final := make(map[string]map[string]*cargo, len(r.compartments))
239		for id, comp := range r.compartments {
240			set := make(map[string]*cargo, len(comp.cargo))
241			for cid, c := range comp.cargo {
242				set[cid] = c
243			}
244			final[id] = set
245		}
246		for _, v := range vops {
247			switch v.op.Kind {
248			case OpLoad:
249				final[v.target.id][v.cargo.id] = v.cargo
250			case OpUnload:
251				delete(final[v.cargo.compartmentID], v.cargo.id)
252			case OpMove:
253				delete(final[v.cargo.compartmentID], v.cargo.id)
254				final[v.target.id][v.cargo.id] = v.cargo
255			}
256		}
257		return final
258	}
